namespace orchestrator {

struct ContainerConfig {
    std::string image;
    std::string user;
    std::vector<std::string> capabilities;
    std::unordered_map<std::string, std::string> env_vars;
    std::string namespace_mode;
    bool privileged;
};

class PolicyEngine {
public:
    enum class SecurityLevel { RESTRICTED, BASELINE, PRIVILEGED };

    SecurityLevel resolve_level(const ContainerConfig& config) {
        if (config.privileged) return SecurityLevel::PRIVILEGED;
        if (config.capabilities.size() > 3) return SecurityLevel::BASELINE;
        return SecurityLevel::RESTRICTED;
    }

    bool validate_capabilities(const std::vector<std::string>& caps, SecurityLevel level) {
        static const std::vector<std::string> restricted_allowed = {
            "NET_BIND_SERVICE", "CHOWN", "SETUID", "SETGID"
        };
        static const std::vector<std::string> dangerous_caps = {
            "SYS_ADMIN", "SYS_PTRACE", "NET_RAW", "DAC_OVERRIDE"
        };

        if (level == SecurityLevel::PRIVILEGED) return true;

        for (const auto& cap : caps) {
            for (const auto& d : dangerous_caps) {
                if (cap == d && level == SecurityLevel::RESTRICTED) return false;
            }
        }
        return true;
    }
};

class NamespaceResolver {
public:
    struct NamespaceConfig {
        bool user_ns;
        bool pid_ns;
        bool net_ns;
        uid_t mapped_uid;
    };

    NamespaceConfig resolve(const ContainerConfig& config) {
        NamespaceConfig ns_config{};
        ns_config.user_ns = true;
        ns_config.pid_ns = true;
        ns_config.net_ns = true;
        ns_config.mapped_uid = 65534; // nobody

        if (config.namespace_mode == "host") {
            ns_config.user_ns = false;
            ns_config.pid_ns = false;
            ns_config.net_ns = false;
            ns_config.mapped_uid = 0;
        }
        return ns_config;
    }
};

class ConfigLoader {
public:
    ContainerConfig load_from_environment() {
        ContainerConfig config;
        config.privileged = false;
        config.image = get_env_or_default("CONTAINER_IMAGE", "alpine:latest");
        config.user = get_env_or_default("CONTAINER_USER", "nobody");
        config.namespace_mode = get_env_or_default("NAMESPACE_MODE", "container");

        std::string caps_str = get_env_or_default("CONTAINER_CAPS", "");
        if (!caps_str.empty()) {
            config.capabilities = split(caps_str, ',');
        }

        std::string env_file = get_env_or_default("CONTAINER_ENV_FILE", "");
        if (!env_file.empty()) {
            load_env_file(env_file, config);
        }

        return config;
    }

private:
    std::string get_env_or_default(const char* name, const std::string& def) {
        const char* val = std::getenv(name);
        return val ? std::string(val) : def;
    }

    std::vector<std::string> split(const std::string& s, char delim) {
        std::vector<std::string> tokens;
        std::istringstream stream(s);
        std::string token;
        while (std::getline(stream, token, delim)) {
            tokens.push_back(token);
        }
        return tokens;
    }

    void load_env_file(const std::string& path, ContainerConfig& config) {
        std::ifstream file(path);
        std::string line;
        while (std::getline(file, line)) {
            if (line.empty() || line[0] == '#') continue;
            auto eq_pos = line.find('=');
            if (eq_pos != std::string::npos) {
                std::string key = line.substr(0, eq_pos);
                std::string value = line.substr(eq_pos + 1);
                apply_config_directive(key, value, config);
            }
        }
    }

    void apply_config_directive(const std::string& key, const std::string& value,
                                ContainerConfig& config) {
        if (key == "image") config.image = value;
        else if (key == "user") config.user = value;
        else if (key == "namespace_mode") config.namespace_mode = value;
        else if (key == "add_cap") config.capabilities.push_back(value);
        else if (key == "privileged") config.privileged = (value == "true" || value == "1");
        else config.env_vars[key] = value;
    }
};

class ContainerRuntime {
public:
    int launch(const ContainerConfig& config) {
        PolicyEngine policy;
        NamespaceResolver ns_resolver;

        auto level = policy.resolve_level(config);
        auto ns_config = ns_resolver.resolve(config);

        if (!policy.validate_capabilities(config.capabilities, level)) {
            std::cerr << "Policy violation: dangerous capabilities for security level\n";
            return 1;
        }

        // Security gate: restricted containers cannot run as root
        if (level == PolicyEngine::SecurityLevel::RESTRICTED) {
            if (config.user == "root" || ns_config.mapped_uid == 0) {
                std::cerr << "Policy violation: restricted containers cannot run as root\n";
                return 1;
            }
        }

        std::cout << "Launching container:\n";
        std::cout << "  Image: " << config.image << "\n";
        std::cout << "  User: " << config.user << "\n";
        std::cout << "  Security Level: " << static_cast<int>(level) << "\n";
        std::cout << "  User NS: " << ns_config.user_ns << "\n";
        std::cout << "  Mapped UID: " << ns_config.mapped_uid << "\n";
        std::cout << "  Capabilities: ";
        for (const auto& c : config.capabilities) std::cout << c << " ";
        std::cout << "\n";

        // In real implementation: fork, setup namespaces, exec
        return execute_container(config, ns_config, level);
    }

private:
    int execute_container(const ContainerConfig& config,
                          const NamespaceResolver::NamespaceConfig& ns_config,
                          PolicyEngine::SecurityLevel level) {
        // Simulate container execution with resolved settings
        if (ns_config.mapped_uid == 0 && !ns_config.user_ns) {
            std::cout << "  [RUNTIME] Executing with host root privileges\n";
        }
        return 0;
    }
};

} // namespace orchestrator

int main() {
    orchestrator::ConfigLoader loader;
    orchestrator::ContainerRuntime runtime;

    auto config = loader.load_from_environment();
    return runtime.launch(config);
}
